head.b:skin:
/* ============================================================================
   Velcuri.io Blogger Theme - Refactored
   Modern, glassmorphic design with improved structure
   ============================================================================ */

/* ============================================================================
   1. CSS VARIABLES & DESIGN TOKENS
   ============================================================================ */
:root {
  /* Colors */
  --bg-dark: #0f172a;
  --bg-card: rgba(30, 41, 59, 0.7);
  --bg-overlay: rgba(255, 255, 255, 0.05);
  --bg-overlay-hover: rgba(255, 255, 255, 0.1);

  --text-primary: #f8fafc;
  --text-secondary: #94a3b8;
  --text-muted: #64748b;

  --accent-blue: #3b82f6;
  --accent-purple: #a855f7;
  --accent-red: #dc2626;

  --glass-border: rgba(255, 255, 255, 0.1);
  --glass-border-hover: rgba(59, 130, 246, 0.5);

  --glow-blue: rgba(59, 130, 246, 0.5);
  --glow-red: rgba(220, 38, 38, 0.5);

  /* Social Colors */
  --discord-bg: #5865F2;
  --telegram-bg: #0088cc;

  /* Typography */
  --font-family: 'Inter', system-ui, -apple-system, sans-serif;
  --font-size-base: 1rem;
  --font-size-sm: 0.875rem;
  --font-size-lg: 1.125rem;
  --font-size-xl: 1.25rem;
  --font-size-2xl: 1.5rem;
  --font-size-3xl: 2rem;
  --font-size-4xl: 2.5rem;
  --font-size-5xl: 3rem;

  --line-height-tight: 1.2;
  --line-height-normal: 1.6;
  --line-height-relaxed: 1.8;

  /* Spacing */
  --spacing-xs: 0.25rem;
  --spacing-sm: 0.5rem;
  --spacing-md: 1rem;
  --spacing-lg: 1.5rem;
  --spacing-xl: 2rem;
  --spacing-2xl: 3rem;

  /* Layout */
  --container-width: 1200px;
  --content-width: 1000px;
  --border-radius: 12px;
  --border-radius-lg: 16px;

  /* Effects */
  --blur-amount: 12px;
  --transition-speed: 0.3s;
  --shadow-sm: 0 4px 15px rgba(0, 0, 0, 0.1);
  --shadow-md: 0 10px 30px rgba(0, 0, 0, 0.2);
  --shadow-lg: 0 20px 50px rgba(0, 0, 0, 0.5);
}

/* ============================================================================
   2. RESET & BASE STYLES
   ============================================================================ */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  margin: 0;
  padding: 0;
  font-family: var(--font-family);
  font-size: var(--font-size-base);
  line-height: var(--line-height-normal);
  background-color: var(--bg-dark);
  color: var(--text-primary);
  min-height: 100vh;
  background-image: radial-gradient(circle at 10% 20%, rgba(59, 130, 246, 0.15) 0%, transparent 20%), radial-gradient(circle at 90% 80%, rgba(139, 92, 246, 0.15) 0%, transparent 20%);
  background-attachment: fixed;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a {
  text-decoration: none;
  color: inherit;
  transition: color var(--transition-speed) ease;
}

a:hover {
  color: var(--accent-blue);
}

a:focus-visible {
  outline: 2px solid var(--accent-blue);
  outline-offset: 4px;
  border-radius: 4px;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

button {
  font-family: inherit;
  border: none;
  background: none;
  cursor: pointer;
}

/* ============================================================================
   3. TYPOGRAPHY
   ============================================================================ */
h1, h2, h3, h4, h5, h6 {
  font-weight: 700;
  line-height: var(--line-height-tight);
  margin-bottom: var(--spacing-md);
  color: var(--text-primary);
}

h1 { font-size: var(--font-size-4xl); font-weight: 800; }
h2 { font-size: var(--font-size-3xl); }
h3 { font-size: var(--font-size-xl); }
h4 { font-size: var(--font-size-lg); }
h5, h6 { font-size: var(--font-size-base); }

p {
  margin-bottom: var(--spacing-md);
  color: var(--text-secondary);
  line-height: var(--line-height-normal);
}

.text-gradient {
  background: linear-gradient(to right, var(--accent-blue), var(--accent-purple));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.text-uppercase {
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

/* ============================================================================
   4. LAYOUT UTILITIES
   ============================================================================ */
.container {
  max-width: var(--container-width);
  margin: 0 auto;
  padding: var(--spacing-xl) var(--spacing-md);
}

.content-wrapper {
  max-width: var(--content-width);
  margin: 0 auto;
}

/* Flexbox */
.flex { display: flex; }
.flex-col { flex-direction: column; }
.flex-wrap { flex-wrap: wrap; }
.items-start { align-items: flex-start; }
.items-center { align-items: center; }
.items-end { align-items: flex-end; }
.justify-start { justify-content: flex-start; }
.justify-center { justify-content: center; }
.justify-end { justify-content: flex-end; }
.justify-between { justify-content: space-between; }

/* Grid */
.grid { display: grid; }
.grid-cols-2 { grid-template-columns: repeat(2, 1fr); }
.grid-cols-3 { grid-template-columns: repeat(3, 1fr); }

/* Gaps */
.gap-xs { gap: var(--spacing-xs); }
.gap-sm { gap: var(--spacing-sm); }
.gap-md { gap: var(--spacing-md); }
.gap-lg { gap: var(--spacing-lg); }
.gap-xl { gap: var(--spacing-xl); }

/* Text Alignment */
.text-left { text-align: left; }
.text-center { text-align: center; }
.text-right { text-align: right; }

/* Spacing */
.mb-sm { margin-bottom: var(--spacing-sm); }
.mb-md { margin-bottom: var(--spacing-md); }
.mb-lg { margin-bottom: var(--spacing-lg); }
.mb-xl { margin-bottom: var(--spacing-xl); }
.mt-xl { margin-top: var(--spacing-xl); }
.mt-2xl { margin-top: var(--spacing-2xl); }

/* ============================================================================
   5. COMPONENT STYLES
   ============================================================================ */

/* Glass Panel */
.glass-panel {
  background: var(--bg-card);
  backdrop-filter: blur(var(--blur-amount));
  -webkit-backdrop-filter: blur(var(--blur-amount));
  border: 1px solid var(--glass-border);
  border-radius: var(--border-radius-lg);
  padding: var(--spacing-lg);
  transition: all var(--transition-speed) ease;
}

.glass-panel:hover {
  border-color: var(--glass-border-hover);
  box-shadow: var(--shadow-md);
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-sm);
  padding: 0.75rem 1.5rem;
  border-radius: var(--border-radius);
  font-size: var(--font-size-base);
  font-weight: 600;
  transition: all var(--transition-speed) ease;
  cursor: pointer;
  border: none;
  font-family: var(--font-family);
}

.btn:focus-visible {
  outline: 2px solid var(--accent-blue);
  outline-offset: 2px;
}

.btn-glass {
  background: var(--bg-overlay);
  backdrop-filter: blur(4px);
  border: 1px solid var(--glass-border);
  color: var(--text-primary);
}

.btn-glass:hover {
  background: var(--bg-overlay-hover);
  border-color: var(--accent-blue);
  box-shadow: 0 0 15px var(--glow-blue);
  transform: translateY(-1px);
}

.btn-glass.active {
  background: rgba(59, 130, 246, 0.2);
  border-color: var(--accent-blue);
  color: white;
  box-shadow: 0 0 15px var(--glow-blue);
}

.btn-primary {
  background: var(--accent-blue);
  color: white;
  border: 1px solid transparent;
}

.btn-primary:hover {
  background: #2563eb;
  box-shadow: 0 0 20px var(--glow-blue);
  transform: translateY(-2px);
}

/* Social Buttons */
.btn-social {
  min-width: 200px;
  padding: 1rem 2rem;
  font-weight: 600;
  color: white;
  border-radius: var(--border-radius);
}

.btn-discord {
  background: var(--discord-bg);
  box-shadow: 0 4px 15px rgba(88, 101, 242, 0.3);
}

.btn-telegram {
  background: var(--telegram-bg);
  box-shadow: 0 4px 15px rgba(0, 136, 204, 0.3);
}

.btn-discord:hover,
.btn-telegram:hover {
  transform: translateY(-2px);
  filter: brightness(1.1);
}

/* Badges */
.badge {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-xs);
  padding: 0.25rem 0.75rem;
  border-radius: 999px;
  font-size: var(--font-size-sm);
  font-weight: 700;
}

.badge-live {
  background: var(--accent-red);
  color: white;
  box-shadow: 0 0 10px var(--glow-red);
  animation: pulse 2s infinite;
}

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.7; }
}

/* Video Container */
.video-wrapper {
  position: relative;
  padding-bottom: 56.25%;
  height: 0;
  background: #000;
  border-radius: var(--border-radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-lg);
  border: 1px solid var(--glass-border);
}

.video-wrapper iframe {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
}

/* Ad Container */
.ad-section {
  margin: var(--spacing-xl) 0;
  text-align: center;
  min-height: 100px;
  display: flex;
  justify-content: center;
  align-items: center;
  background: rgba(255, 255, 255, 0.02);
  border-radius: var(--border-radius);
  padding: var(--spacing-md);
  border: 1px solid var(--glass-border);
}

.ad-container {
  margin: var(--spacing-xl) 0;
  text-align: center;
  min-height: 100px;
  display: flex;
  justify-content: center;
  align-items: center;
  background: rgba(255, 255, 255, 0.02);
  border-radius: var(--border-radius);
  padding: var(--spacing-md);
}

/* ============================================================================
   6. PAGE-SPECIFIC COMPONENTS
   ============================================================================ */

/* Blog Header */
.blog-header {
  text-align: center;
  padding: var(--spacing-xl) 0;
  margin-bottom: var(--spacing-xl);
}

.blog-title {
  font-size: var(--font-size-5xl);
  font-weight: 800;
  margin: 0;
}

/* Match/Event Card */
.event-header {
  text-align: center;
  padding: var(--spacing-xl);
}

.event-league {
  color: var(--accent-blue);
  font-size: var(--font-size-base);
  font-weight: 700;
  display: inline-block;
  margin-bottom: var(--spacing-sm);
}

.event-title {
  font-size: var(--font-size-4xl);
  margin: var(--spacing-md) 0;
  line-height: var(--line-height-tight);
}

.event-meta {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: var(--spacing-lg);
  margin-top: var(--spacing-lg);
  color: var(--text-secondary);
  font-size: var(--font-size-lg);
  flex-wrap: wrap;
}

/* Match-specific classes (for post content) */
.match-container {
  max-width: var(--content-width);
  margin: 0 auto;
  padding: var(--spacing-md);
}

.match-header {
  text-align: center;
  padding: var(--spacing-xl);
  margin-bottom: var(--spacing-xl);
}

.match-info h1 {
  font-size: var(--font-size-4xl);
  margin: var(--spacing-md) 0;
  line-height: var(--line-height-tight);
}

.league-tag {
  color: var(--accent-blue);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  font-weight: 700;
  font-size: var(--font-size-base);
  display: inline-block;
  margin-bottom: var(--spacing-sm);
}

.match-meta {
  display: flex;
  justify-content: center;
  gap: var(--spacing-lg);
  align-items: center;
  margin-top: var(--spacing-lg);
  color: var(--text-secondary);
  font-size: var(--font-size-lg);
  flex-wrap: wrap;
}

.time-tag {
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
}

.live-badge {
  background: var(--accent-red);
  color: white;
  padding: 0.25rem 0.75rem;
  border-radius: 999px;
  font-size: var(--font-size-sm);
  font-weight: 800;
  box-shadow: 0 0 10px var(--glow-red);
  animation: pulse 2s infinite;
  display: inline-block;
}

.video-container {
  position: relative;
  padding-bottom: 56.25%;
  height: 0;
  background: #000;
  border-radius: var(--border-radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-lg);
  border: 1px solid var(--glass-border);
  margin-bottom: var(--spacing-lg);
}

.video-container iframe {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
}

/* Player/Stream Section */
.player-section {
  padding: var(--spacing-xl);
  margin-top: var(--spacing-xl);
}

.server-list {
  margin-bottom: var(--spacing-lg);
}

.server-list h3 {
  color: var(--text-secondary);
  text-transform: uppercase;
  font-size: var(--font-size-sm);
  letter-spacing: 0.05em;
  margin-bottom: var(--spacing-md);
  font-weight: 600;
}

.stream-buttons {
  display: flex;
  gap: var(--spacing-md);
  flex-wrap: wrap;
  margin-bottom: var(--spacing-lg);
}

.stream-btn {
  padding: 0.75rem 1.5rem;
  background: var(--bg-overlay);
  border: 1px solid var(--glass-border);
  color: var(--text-secondary);
  cursor: pointer;
  border-radius: var(--border-radius);
  display: flex;
  align-items: center;
  gap: 0.75rem;
  transition: all var(--transition-speed) ease;
  font-weight: 500;
  font-family: var(--font-family);
  font-size: var(--font-size-base);
}

.stream-btn:hover {
  background: var(--bg-overlay-hover);
  color: var(--text-primary);
  border-color: var(--accent-blue);
}

.stream-btn.active {
  background: rgba(59, 130, 246, 0.2);
  border-color: var(--accent-blue);
  color: white;
  box-shadow: 0 0 15px var(--glow-blue);
}

.stream-btn svg {
  flex-shrink: 0;
}

.stream-controls {
  margin-bottom: var(--spacing-lg);
}

.stream-controls h3 {
  color: var(--text-secondary);
  font-size: var(--font-size-sm);
  font-weight: 600;
  margin-bottom: var(--spacing-md);
}

/* Social Links */
.social-links {
  display: flex;
  gap: var(--spacing-md);
  justify-content: center;
  flex-wrap: wrap;
  margin: var(--spacing-2xl) 0;
}

.discord-btn,
.telegram-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.75rem;
  padding: 1rem 2rem;
  border-radius: var(--border-radius);
  text-decoration: none;
  font-weight: 600;
  color: white;
  transition: all 0.2s ease;
  min-width: 200px;
  font-family: var(--font-family);
}

.discord-btn {
  background: var(--discord-bg);
  box-shadow: 0 4px 15px rgba(88, 101, 242, 0.3);
}

.telegram-btn {
  background: var(--telegram-bg);
  box-shadow: 0 4px 15px rgba(0, 136, 204, 0.3);
}

.discord-btn:hover,
.telegram-btn:hover {
  transform: translateY(-2px);
  filter: brightness(1.1);
  color: white;
}

.discord-btn svg,
.telegram-btn svg {
  flex-shrink: 0;
}

/* Footer */
.site-footer {
  text-align: center;
  padding: var(--spacing-xl);
  color: var(--text-secondary);
  border-top: 1px solid var(--glass-border);
  margin-top: var(--spacing-2xl);
}

/* ============================================================================
   7. BLOGGER-SPECIFIC OVERRIDES
   ============================================================================ */
.blog-posts {
  margin: 0;
}

.post-outer {
  margin-bottom: var(--spacing-xl);
  border: none;
}

.post-body {
  font-size: var(--font-size-base);
  line-height: var(--line-height-normal);
  padding: 0;
}

/* Hide default Blogger elements */
.post-title,
.date-header,
.post-footer,
.blog-pager,
.feed-links,
.post-timestamp,
.post-comment-link,
.post-labels {
  display: none;
}

/* Custom post elements */
.post-title-custom {
  font-size: var(--font-size-2xl);
  margin-bottom: var(--spacing-md);
  font-weight: 700;
}

.post-title-custom a {
  color: var(--text-primary);
  transition: color var(--transition-speed) ease;
}

.post-title-custom a:hover {
  color: var(--accent-blue);
}

.post-meta-custom {
  display: flex;
  gap: var(--spacing-md);
  color: var(--text-muted);
  font-size: var(--font-size-sm);
  align-items: center;
}

.post-date {
  display: flex;
  align-items: center;
  gap: var(--spacing-xs);
}

.read-more-container {
  text-align: center;
}

.post-outer {
  margin-bottom: var(--spacing-2xl);
}

/* ============================================================================
   8. RESPONSIVE DESIGN
   ============================================================================ */

/* Tablet */
@media (max-width: 1024px) {
  :root {
    --container-width: 100%;
    --font-size-4xl: 2rem;
    --font-size-5xl: 2.5rem;
  }

  .grid-cols-3 {
    grid-template-columns: repeat(2, 1fr);
  }
}

/* Mobile */
@media (max-width: 768px) {
  :root {
    --font-size-3xl: 1.5rem;
    --font-size-4xl: 1.75rem;
    --font-size-5xl: 2rem;
    --spacing-xl: 1.5rem;
    --spacing-2xl: 2rem;
  }

  .container {
    padding: var(--spacing-xs);
  }

  .grid-cols-2,
  .grid-cols-3 {
    grid-template-columns: 1fr;
  }

  .event-meta,
  .match-meta {
    flex-direction: column;
    gap: var(--spacing-sm);
  }

  .stream-buttons {
    flex-direction: column;
  }

  .stream-btn {
    width: 100%;
    justify-content: flex-start;
  }

  .btn-social,
  .discord-btn,
  .telegram-btn {
    min-width: 100%;
  }

  .social-links {
    flex-direction: column;
  }

  .match-container {
    padding: 0;
    width: 100%;
  }

  .match-header {
    padding: var(--spacing-sm);
    margin-bottom: var(--spacing-md);
    border-radius: var(--border-radius);
  }

  .player-section {
    padding: var(--spacing-sm);
    margin-top: var(--spacing-md);
    border-radius: var(--border-radius);
  }

  .video-container {
    border-radius: var(--border-radius);
    margin-bottom: var(--spacing-md);
  }
}

@media (max-width: 480px) {
  :root {
    --font-size-4xl: 1.5rem;
    --font-size-5xl: 1.75rem;
  }

  .btn {
    padding: 0.625rem 1.25rem;
    font-size: var(--font-size-sm);
  }

  .event-header,
  .player-section {
    padding: var(--spacing-md);
  }
}

/* ============================================================================
   9. ACCESSIBILITY IMPROVEMENTS
   ============================================================================ */

/* Focus indicators */
*:focus-visible {
  outline: 2px solid var(--accent-blue);
  outline-offset: 2px;
}

/* Skip to content link */
.skip-to-content {
  position: absolute;
  top: -100px;
  left: 0;
  background: var(--accent-blue);
  color: white;
  padding: var(--spacing-sm) var(--spacing-md);
  z-index: 100;
  border-radius: 0 0 var(--border-radius) 0;
}

.skip-to-content:focus {
  top: 0;
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/* High contrast mode */
@media (prefers-contrast: high) {
  :root {
    --glass-border: rgba(255, 255, 255, 0.3);
    --text-secondary: #cbd5e1;
  }
}

/* ============================================================================
   10. UTILITY CLASSES
   ============================================================================ */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}
